This gives the weekday-first real-output validation the previous BLOCKING was about. Let me do it — it's cheap and it's the grader-parity/conformance check for the rework.

Also negative checks:
1. Real `lstart` output → non-null, matches `^e\d+$`.
2. `'Mon Oct 26 19:23:27 2026'` → epoch check vs DateTime.
3. Junk/empty/French month → null.
4. Two parses of the same string give equal tokens (stability); a different start time gives a different token (two incarnations differ).
5. Guard round-trip: `<pid> <identity>\n` parse via `_parseOverlayGuard` logic — validated by the suite already.

Let me write the script.

arguments.command:
cat > /tmp/review/lstart_check.dart <<'EOF'
import 'dart:io';

// Verbatim copy of the PR's psLstartIdentity (bin/fah_dap_scoped.dart).
String? psLstartIdentity(String lstart) {
  const months = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12,
  };
  final m = RegExp(
    r'^\w{3} (\w{3}) +(\d{1,2}) (\d{2}):(\d{2}):(\d{2}) (\d{4})$',
  ).firstMatch(lstart.trim());
  final month = m == null ? null : months[m.group(1)];
  if (month == null) return null;
  try {
    final start = DateTime(
      int.parse(m!.group(6)!), month, int.parse(m.group(2)!),
      int.parse(m.group(3)!), int.parse(m.group(4)!), int.parse(m.group(5)!),
    );
    return 'e${start.millisecondsSinceEpoch ~/ 1000}';
  } on Object {
    return null;
  }
}

void main() {
  final me = Process.runSync('ps', ['-o', 'lstart=', '-p', '$pid']);
  final real = (me.stdout as String).trim();
  stdout.writeln('real lstart        : "$real"');
  final tok = psLstartIdentity(real);
  stdout.writeln('parsed token       : $tok');
  stdout.writeln('token shape ok     : ${RegExp(r"^e\d+$").hasMatch(tok ?? "")}');
  // stability: same input -> same token; different start -> different token
  final again = psLstartIdentity(real);
  final other = psLstartIdentity(real.replaceAll(RegExp(r'\d\d:\d\d:\d\d'), '23:59:58'));
  stdout.writeln('stable re-parse    : ${tok == again}');
  stdout.writeln('other incarnation   differs: ${tok != other}');
  // negatives
  stdout.writeln('junk -> null       : ${psLstartIdentity('garbage') == null}');
  stdout.writeln('empty -> null      : ${psLstartIdentity('') == null}');
  stdout.writeln('non-C month -> null: ${psLstartIdentity('Tue déc 13 13:35:05 2026') == null}');
  // known pinned samples
  final s1 = psLstartIdentity('Tue Oct 13 13:35:05 2026');
  final s2 = psLstartIdentity('Mon Sep  1 01:02:03 2026');
  stdout.writeln('weekday-first match: ${s1 == 'e${DateTime(2026,10,13,13,35,5).millisecondsSinceEpoch ~/ 1000}'}');
  stdout.writeln('space-padded day   : ${s2 == 'e${DateTime(2026,9,1,1,2,3).millisecondsSinceEpoch ~/ 1000}'}');
}
EOF
